with base as (select * from stores where opened_date between '2023-07-01' and '2024-03-21' and sqft is not null), stores_stats as (select region, round((100 * sum(case when region = 'West' then 1 else 0 end)) / count(*), 1) as pct_west, round((100 * sum(case when city = 'Bangkok' then 1 else 0 end)) / count(*), 1) as pct_bangkok from base group by region) select region, pct_bangkok from stores_stats order by pct_bangkok desc, 1 asc
